class Resource extends Vector {
 heading='Contours of a quieter place.';note='Every line is a measured elevation, not a repeated ornament.';
 build(){const seed=this.number('seed',24,1,100),levels=this.number('detail',16,6,26);const rand=seedRandom(seed);const peaks=Array.from({length:6},()=>({x:rand()*720,y:rand()*420,r:75+rand()*160,a:.5+rand()}));const cols=72,rows=42,step=10;const field=Array.from({length:rows+1},(_,y)=>Array.from({length:cols+1},(_,x)=>peaks.reduce((sum,p)=>sum+p.a*Math.exp(-((x*step-p.x)**2+(y*step-p.y)**2)/(p.r*p.r)),0)));const max=Math.max(...field.flat());let paths='';for(let level=1;level<=levels;level++){const threshold=max*level/(levels+1);let d='';for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){const values=[field[y][x],field[y][x+1],field[y+1][x+1],field[y+1][x]],points=[[x*step,y*step],[(x+1)*step,y*step],[(x+1)*step,(y+1)*step],[x*step,(y+1)*step]],crossings=[];for(let edge=0;edge<4;edge++){const next=(edge+1)%4;if((values[edge]>=threshold)===(values[next]>=threshold))continue;const t=(threshold-values[edge])/(values[next]-values[edge]);crossings.push([points[edge][0]+(points[next][0]-points[edge][0])*t,points[edge][1]+(points[next][1]-points[edge][1])*t]);}for(let n=0;n+1<crossings.length;n+=2)d+=`M${crossings[n][0].toFixed(1)} ${crossings[n][1].toFixed(1)}L${crossings[n+1][0].toFixed(1)} ${crossings[n+1][1].toFixed(1)}`;}paths+=`<path d="${d}" fill="none" stroke="${this.color}" stroke-width="${level%4===0?1.6:.65}" opacity="${.18+level/levels*.57}"/>`;}
 return this.svg(`<rect x="28" y="20" width="664" height="380" fill="#172825" rx="8"/>${paths}<path d="M55 55h32m-16-16v32M633 365h32m-16-16v32" stroke="#d4debf77" fill="none"/><text x="52" y="374" fill="#b2c2b1" font-family="monospace" font-size="9" letter-spacing="2">FIELD ${String(seed).padStart(3,'0')} / ${levels} LEVELS</text>`,'Seeded Gaussian terrain traced with marching-square contour segments.');}
}
